import React from 'react';
import {useState} from 'react'
import { useNavigate, useLocation } from "react-router-dom";
import './Menu.scss';
import MenuButton from '../Buttons/Menu-button/Menu-button';
import { useTranslation } from 'react-i18next';
import { FiAlignLeft, FiChevronLeft, FiChevronsLeft, FiChevronsRight, FiCoffee, FiEye, FiFolder, FiHelpCircle, FiLayers, FiSettings, FiTrash } from 'react-icons/fi';

const Menu = ({ onToggleMenu, isMenuClosed }) => {
  const navigate = useNavigate();
  const location = useLocation(); 

  const goToVisualDesign = () => {
    navigate('/visual-testing');
  };

  const goToDesignSystem = () => {
    navigate('/design-system');
  };

  const goToEndToEnd = () => {
    navigate('/end-to-end');
  };

  const goToProofreading = () => {
    navigate('/proofreading');
  };

  const { t } = useTranslation();

  const [isLeft, setIsLeft] = useState(true);

  const toggleChevron = () => {
    setIsLeft(!isLeft);
  };

  return (
        <nav className='lou-bg-white lou-rounded lou-border lou-border-dark-50 lou-text-dark lou-grid lou-grid-rows-[1fr_auto] items-center' lou-component='menu'>
      <section>
        <div className={`menu--header lou-items-center lou-border-b lou-border-dark-50 lou-p-2xs lou-pl-sm lou-p-xs ${isMenuClosed ? `lou-w-full lou-justify-center lou-grid lou-p-xs ` : `lou-p-xs lou-grid lou-grid-cols-[1fr_auto]`}`}>
          {isMenuClosed ?
            <svg width="18" height="17" viewBox="0 0 18 17" fill="none" xmlns="http://www.w3.org/2000/svg" className='lou-justify-center lou-align-center lou-m-xs'>
              <path d="M0.132 17V0.0559993H2.82L9.492 10.448H8.124L14.772 0.0559993H17.484V17H13.716V6.416L14.388 6.584L10.044 13.352H7.548L3.228 6.584L3.876 6.416V17H0.132Z" fill="#020E19"/>
            </svg>
            :
            <svg width='100' height='24' viewBox='0 0 100 24' fill='none' xmlns='http://www.w3.org/2000/svg'>
              <path d='...' fill='black'/>
            </svg>
          }
          <button onClick={onToggleMenu} className={`${isMenuClosed ? 'lou-absolute' : ''} menu--header-cta lou-opacity-0 lou-transition lou-duration-300 lou-text-xl lou-text-dark-500 hover:lou-bg-dark-30 lou-rounded-sm lou-p-xs`}>
            {isLeft && !isMenuClosed ? <FiChevronsLeft /> : <FiChevronsRight />}
          </button>
        </div>
        <div className={isMenuClosed ? `lou-w-full lou-justify-center lou-grid lou-p-xs ` : `lou-p-xs`}>
          <MenuButton
            text={t('menu.items.visual-design')}
            onClick={goToVisualDesign}
            icon={<FiEye />}
            isActive={location.pathname === '/visual-testing'}  // Vérifie l'URL actuelle
            isMenuClosed={isMenuClosed}
          />
          <MenuButton
            text={t('menu.items.design-system')}
            onClick={goToDesignSystem}
            icon={<FiLayers />}
            isActive={location.pathname === '/design-system'}  // Vérifie l'URL actuelle
            isMenuClosed={isMenuClosed}
          />
          <MenuButton
            text={t('menu.items.end-to-end')}
            onClick={goToEndToEnd}
            icon={<FiFolder />}
            isActive={location.pathname === '/end-to-end'}  // Vérifie l'URL actuelle
            isMenuClosed={isMenuClosed}
          />
          <MenuButton
            text={t('menu.items.proofreading')}
            onClick={goToProofreading}
            icon={<FiAlignLeft />}
            isActive={location.pathname === '/proofreading'}  // Vérifie l'URL actuelle
            isMenuClosed={isMenuClosed}
          />
        </div>
      </section>
      <section className='lou-border-t lou-border-dark-50 lou-p-xs'>
        <MenuButton
          text={t('menu.actions.settings')}
          icon={<FiSettings />}
          isActive={location.pathname === '/settings'}  // Vérifie l'URL actuelle
          isMenuClosed={isMenuClosed}
        />
        <MenuButton
          text={t('menu.actions.help')}
          icon={<FiHelpCircle />}
          isActive={location.pathname === '/help'}  // Vérifie l'URL actuelle
          isMenuClosed={isMenuClosed}
        />
      </section>
    </nav>
  );
};

export default Menu;
